INSERT INTO public.lessons (id, module_id, course_id, slug, title, description, youtube_video_id, duration_minutes, order_index, objectives, tags, skills_taught) VALUES (
  'e1000000-0601-4000-8000-000000000001'::uuid, 'e1000000-0006-4000-8000-000000000001'::uuid, 'e1000000-0000-4000-8000-000000000001'::uuid, 'm06-l01-transistors-mosfets-as-low-voltage-digital-switches', 'Module 06 - Lesson 1: Transistors & MOSFETs as Low-Voltage Digital Switches', 'Understand saturation mode in NPN bipolar transistors (2N2222) and logic-level N-channel MOSFETs (2N7000/IRLZ44N) for switching DC loads up to 500mA safely. Practice: Calculate base resistor value for 2N2222 given load current of 100mA and minimum hFE of 10; build the breadboard driver stage.', 'cuOFG_ISHno', 12, 1,
  ARRAY['Master Transistors & MOSFETs as Low-Voltage Digital Switches', 'Apply: Calculate base resistor value for 2N2222 given load current of 100mA and minimum hFE of 10; build the breadboard driver stage.', 'Strict <=3.3V DC limits & ethical ROE']::text[],
  ARRAY['iot', 'module-06', 'hardware-security', 'no-quizzes']::text[],
