INSERT INTO public.lessons (id, module_id, course_id, slug, title, description, youtube_video_id, duration_minutes, order_index, objectives, tags, skills_taught) VALUES (
  'e1000000-0602-4000-8000-000000000001'::uuid, 'e1000000-0006-4000-8000-000000000001'::uuid, 'e1000000-0000-4000-8000-000000000001'::uuid, 'm06-l02-inductive-load-protection-flyback-diode-clamping', 'Module 06 - Lesson 2: Inductive Load Protection & Flyback Diode Clamping', 'Analyze Lenz''s Law and the high-voltage reverse inductive spike generated when de-energizing coils (buzzers, relays, small motors); wire parallel flyback diodes (1N4007). Practice: Observe voltage transient on an inductive coil upon switch open with and without a reverse-biased flyback clamping diode.', 'haUWO7BGYTE', 8, 2,
