INSERT INTO public.lessons (id, module_id, course_id, slug, title, description, youtube_video_id, duration_minutes, order_index, objectives, tags, skills_taught) VALUES (
  'e1000000-0702-4000-8000-000000000001'::uuid, 'e1000000-0007-4000-8000-000000000001'::uuid, 'e1000000-0000-4000-8000-000000000001'::uuid, 'm07-l02-embedded-ip-stacks-dhcp-dns-tcp-udp-in-microcontrollers', 'Module 07 - Lesson 2: Embedded IP Stacks: DHCP, DNS, TCP & UDP in Microcontrollers', 'Examine the lightweight IP (lwIP) stack implemented in embedded firmware; trace packet encapsulation across Link, Internet, and Transport layers. Practice: Resolve a local hostname using embedded mDNS (`ESPmDNS`), send a UDP heartbeat broadcast, and measure network round-trip time.', 'e7vHlcEjT78', 9, 2,
  ARRAY['Master Embedded IP Stacks: DHCP, DNS, TCP & UDP in Microcontrollers', 'Apply: Resolve a local hostname using embedded mDNS (`ESPmDNS`), send a UDP heartbeat broadcast, and measure network round-trip time.', 'Strict <=3.3V DC limits & ethical ROE']::text[],
