INSERT INTO public.lessons (id, module_id, course_id, slug, title, description, youtube_video_id, duration_minutes, order_index, objectives, tags, skills_taught) VALUES (
  'e1000000-0801-4000-8000-000000000001'::uuid, 'e1000000-0008-4000-8000-000000000001'::uuid, 'e1000000-0000-4000-8000-000000000001'::uuid, 'm08-l01-mqtt-architecture-broker-topics-qos-retained-messages', 'Module 08 - Lesson 1: MQTT Architecture: Broker, Topics, QoS & Retained Messages', 'Understand MQTT publish/subscribe architecture, topic hierarchies (`sensors/room1/temp`), Quality of Service levels (QoS 0, 1, 2), and retained message flags. Practice: Install Eclipse Mosquitto on lab workstation; subscribe to `#` wildcard using `mosquitto_sub` and publish test messages with `mosquitto_pub`.', 'EIxdz-2rhLs', 4, 1,
  ARRAY['Master MQTT Architecture: Broker, Topics, QoS & Retained Messages', 'Apply: Install Eclipse Mosquitto on lab workstation; subscribe to `#` wildcard using `mosquitto_sub` and publish test messages with `mosquitto_pub`.', 'Strict <=3.3V DC limits & ethical ROE']::text[],
