INSERT INTO public.lessons (id, module_id, course_id, slug, title, description, youtube_video_id, duration_minutes, order_index, objectives, tags, skills_taught) VALUES (
  'e1000000-0901-4000-8000-000000000001'::uuid, 'e1000000-0009-4000-8000-000000000001'::uuid, 'e1000000-0000-4000-8000-000000000001'::uuid, 'm09-l01-protocol-comparison-coap-vs-http-vs-mqtt-in-iot', 'Module 09 - Lesson 1: Protocol Comparison: CoAP vs HTTP vs MQTT in IoT', 'Compare architectural trade-offs: CoAP (UDP-based binary REST with CBOR), HTTP/REST (stateless, text/JSON overhead), and MQTT (lightweight broker-mediated pub/sub). Practice: Measure bandwidth consumption, packet overhead, and battery power implications for sending 100 sensor readings across HTTP, MQTT, and CoAP.', 'zpKJuJs_zfg', 10, 1,
  ARRAY['Master Protocol Comparison: CoAP vs HTTP vs MQTT in IoT', 'Apply: Measure bandwidth consumption, packet overhead, and battery power implications for sending 100 sensor readings across HTTP, MQTT, and CoAP.', 'Strict <=3.3V DC limits & ethical ROE']::text[],
  ARRAY['iot', 'module-09', 'hardware-security', 'no-quizzes']::text[],
