  'e1000000-1801-4000-8000-000000000001'::uuid, 'e1000000-0018-4000-8000-000000000001'::uuid, 'e1000000-0000-4000-8000-000000000001'::uuid, 'm24-l01-visual-inspection-identifying-uart-jtag-swd-pads-on-pcbs', 'Module 24 - Lesson 1: Visual Inspection: Identifying UART, JTAG & SWD Pads on PCBs', 'Inspect printed circuit board (PCB) layouts: identify common debug pin groupings, fiducial markers, unpopulated header pads, and traces running to microcontroller pins. Practice: Examine high-resolution PCB photographs and physical boards; locate probable UART (TX, RX), SWD (SWDIO, SWCLK), and JTAG (TDI, TDO, TCK, TMS) pads.', 'Lg_H6wEhfdQ', 7, 1,
  ARRAY['Master Visual Inspection: Identifying UART, JTAG & SWD Pads on PCBs', 'Apply: Examine high-resolution PCB photographs and physical boards; locate probable UART (TX, RX), SWD (SWDIO, SWCLK), and JTAG (TDI, TDO, TCK, TMS) pads.', 'Strict <=3.3V DC limits & ethical ROE']::text[],
