  ARRAY['Master Reading Non-Sensitive Serial Boot Telemetry via 3.3V UART Adapters', 'Apply: Connect RX and GND probes to test board; cycle power to capture ROM boot messages and identify CPU clock rate and flash chip model.', 'Strict <=3.3V DC limits & ethical ROE']::text[],
