  'e1000000-1901-4000-8000-000000000001'::uuid, 'e1000000-0019-4000-8000-000000000001'::uuid, 'e1000000-0000-4000-8000-000000000001'::uuid, 'm25-l01-mirai-iot-botnet-historical-attack-chain-analysis', 'Module 25 - Lesson 1: Mirai & IoT Botnet Historical Attack Chain Analysis', 'Analyze historical Mirai botnet architecture: default credential scanning, loader daemons, memory-only execution, C2 domain resolution, and synchronized volumetric DDoS vectors. Practice: Deconstruct a documented Mirai attack timeline; trace the sequence from initial Telnet brute-force to C2 registration and attack command delivery.', '1pywzRTJDaY', 29, 1,
  ARRAY['Master Mirai & IoT Botnet Historical Attack Chain Analysis', 'Apply: Deconstruct a documented Mirai attack timeline; trace the sequence from initial Telnet brute-force to C2 registration and attack command delivery.', 'Strict <=3.3V DC limits & ethical ROE']::text[],
