  'e1000000-1902-4000-8000-000000000001'::uuid, 'e1000000-0019-4000-8000-000000000001'::uuid, 'e1000000-0000-4000-8000-000000000001'::uuid, 'm25-l02-identifying-botnet-command-control-c2-telemetry-in-logs', 'Module 25 - Lesson 2: Identifying Botnet Command & Control (C2) Telemetry in Logs', 'Inspect synthetic firewall logs, DNS query records, and NetFlow telemetry for indicators of botnet activity: high-frequency port scanning, anomalous DNS requests, and unusual outbound connections. Practice: Analyze a 10,000-line DNS query log; identify an infected IoT device beaconing to a dynamic DNS C2 domain at regular intervals.', 'UVFmC178_Vs', 9, 2,
  ARRAY['Master Identifying Botnet Command & Control (C2) Telemetry in Logs', 'Apply: Analyze a 10,000-line DNS query log; identify an infected IoT device beaconing to a dynamic DNS C2 domain at regular intervals.', 'Strict <=3.3V DC limits & ethical ROE']::text[],
  ARRAY['iot', 'module-25', 'hardware-security', 'no-quizzes']::text[],
